const end = new Date();
const start = new Date(end.getTime() - 24 * 3600 * 1000);
const query = new URLSearchParams({
  nodeKey: env.get("PD_NODE_KEY") || "ProductionCount",
  start: start.toISOString(),
  end: end.toISOString(),
});
msg.url = `${env.get("PD_URL")}/api/v1/history/${encodeURIComponent(env.get("PD_MACHINE_ID"))}/summaries?${query}`;
msg.headers = { authorization: `Bearer ${env.get("PD_SERVICE_TOKEN")}` };
return msg;

if (msg.statusCode === 429) {
  // The rate limiter answers in plain text; wait for the window to reset.
  node.warn(`Rate limited; retry after ${msg.headers["ratelimit-reset"]} s`);
  return null;
}
if (msg.statusCode !== 200) {
  // 401: token unknown, expired or revoked. 403: machine not granted.
  node.error(`HTTP ${msg.statusCode}: ${JSON.stringify(msg.payload)}`, msg);
  return null;
}
msg.payload = msg.payload.map((hour) => ({
  hour: hour.bucket,
  average: hour.average, // null: not every sample was Good, so the average is unknown
  samples: hour.samples,
  goodSamples: hour.good,
}));
return msg;
